<template>
 <section class="work-panel discussion"><div class="section-heading"><div><h2>{{ $ui('评论') }}</h2><p class="store-muted">{{ $ui('评论用于讨论，不计入评分与评价。') }}</p></div><button class="secondary-button" :disabled="loading" @click="load(false)">{{ $ui('刷新') }}</button></div>
 <form v-if="session" class="store-form" @submit.prevent="post()"><label>{{ $ui('发表评论') }}<textarea v-model="draft" maxlength="2000" required rows="3" /></label><button class="primary-button" :disabled="busy || !draft.trim()">{{ $ui('发表评论') }}</button></form><router-link v-else class="secondary-button" :to="{path:'/login',query:{return:route.fullPath}}">{{ $ui('登录后评论') }}</router-link>
 <p v-if="notice" class="form-success" role="status">{{ $ui(notice) }}</p><p v-if="error" class="form-error" role="alert">{{ $ui(error) }}</p><p v-if="loading && !comments.length" role="status">{{ $ui('正在读取评论…') }}</p><p v-else-if="!comments.length && !error" class="store-muted">{{ $ui('暂无评论。') }}</p>
 <StoreCommentEntry v-for="comment in comments" :key="comment.id" :item-id="itemId" :comment="comment" :session="session" :can-reply="!comment.deleted" @reply="startReply(comment,$event)" @changed="load(false)">
  <div v-if="threads[comment.id]" class="comment-replies"><StoreCommentEntry v-for="reply in threads[comment.id].rows" :key="reply.id" :item-id="itemId" :comment="reply" :session="session" :can-reply="!comment.deleted" @reply="startReply(comment,$event)" @changed="loadReplies(comment,false,threads[comment.id].expanded ? 50 : 2)" /><p v-if="threads[comment.id].loading" role="status">{{ $ui('正在读取评论…') }}</p><button v-if="threads[comment.id].rows.length < threads[comment.id].total" class="replies-toggle" :disabled="threads[comment.id].loading" @click="expand(comment)">{{ $ui(threads[comment.id].expanded ? '再加载最多50条回复' : '展开回复（共{0}条）',[threads[comment.id].total]) }}</button><button v-if="threads[comment.id].expanded" class="replies-toggle" @click="collapse(comment)">{{ $ui('收起回复') }}</button></div>
  <form v-if="target?.root.id === comment.id && session" class="store-form reply-form" @submit.prevent="post(target)"><label>{{ $ui('回复 {0}',[target.to.author_name]) }}<textarea v-model="replyDraft" maxlength="2000" required rows="3" /></label><div class="actions"><button class="primary-button" :disabled="busy || !replyDraft.trim()">{{ $ui('回复') }}</button><button type="button" class="secondary-button" @click="target=undefined;replyDraft=''">{{ $ui('取消') }}</button></div></form>
 </StoreCommentEntry>
 <button v-if="comments.length < total" class="secondary-button" :disabled="loading" @click="load(true)">{{ $ui('更多评论') }}</button>
 </section>
</template>
<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,reactive} from 'vue';
import {useRoute} from 'vue-router';
import {store,type StoreComment} from '@/api/store';
import type {Session} from '@/api/platform';
import StoreCommentEntry from './StoreCommentEntry.vue';
const props=defineProps<{itemId:string;session?:Session}>(),route=useRoute();
const comments=ref<StoreComment[]>([]),total=ref(0),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),draft=ref(''),replyDraft=ref('');
type Target={root:StoreComment;to:StoreComment};const target=ref<Target>();
const threads=reactive<Record<string,{expanded:boolean;loading:boolean;rows:StoreComment[];total:number}>>({});
const keys=new Map<string,string>();let active=true;
function key(value:unknown){const fingerprint=JSON.stringify(value);if(!keys.has(fingerprint))keys.set(fingerprint,crypto.randomUUID());return keys.get(fingerprint)!;}
async function load(more=false){if(loading.value)return;loading.value=true;error.value='';try{const page=await store.comments(props.itemId,more?comments.value.length:0);if(!active)return;comments.value=more?[...new Map([...comments.value,...page.data].map(r=>[r.id,r])).values()]:page.data;total.value=page.pagination.total;if(!more){target.value=undefined;for(const id of Object.keys(threads))delete threads[id];}await Promise.all(page.data.filter(c=>c.reply_count>0).map(c=>loadReplies(c,false,2)));}catch(e){if(active)error.value=e instanceof Error?e.message:'评论操作失败，请重试。';}finally{if(active)loading.value=false;}}
async function loadReplies(root:StoreComment,more=false,take=50){const thread=threads[root.id]|| (threads[root.id]={expanded:false,loading:false,rows:[],total:root.reply_count});if(thread.loading)return;thread.loading=true;try{const page=await store.comments(props.itemId,more?thread.rows.length:0,root.id,take);if(!active)return;thread.rows=more?[...thread.rows,...page.data]:page.data;thread.total=page.pagination.total;return true;}catch(e){if(active)error.value=e instanceof Error?e.message:'评论操作失败，请重试。';}finally{thread.loading=false;}}
async function expand(root:StoreComment){const thread=threads[root.id];if(!thread || thread.loading)return;if(await loadReplies(root,thread.expanded,50))thread.expanded=true;}
function collapse(root:StoreComment){const thread=threads[root.id];if(thread.loading)return;thread.expanded=false;thread.rows=thread.rows.slice(0,2);}
function startReply(root:StoreComment,to:StoreComment){target.value={root,to};replyDraft.value='';}
async function post(reply?:Target){if(busy.value)return;busy.value=true;error.value='';const value={body:reply?replyDraft.value:draft.value,...(reply?{rootId:reply.root.id,replyToId:reply.to.id}:{})};try{await store.comment(props.itemId,value,key(value));keys.delete(JSON.stringify(value));if(!active)return;if(reply){replyDraft.value='';target.value=undefined;reply.root.reply_count++;await loadReplies(reply.root,false,2);threads[reply.root.id].expanded=false;notice.value='回复已发布。';}else{draft.value='';await load(false);}}catch(e){if(active)error.value=e instanceof Error?e.message:'评论操作失败，请重试。';}finally{if(active)busy.value=false;}}
onMounted(()=>void load());onBeforeUnmount(()=>{active=false;});
</script>
<style>
.discussion .store-form{margin-block:20px}.comment-entry{display:flex;gap:14px;margin-top:24px;min-width:0}.comment-avatar{display:grid;place-items:center;flex-shrink:0;width:36px;height:36px;border-radius:50%;background:var(--market-accent-soft);color:var(--nc-accent);font-weight:650}.comment-content{flex:1;min-width:0}.comment-byline{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:13px}.comment-byline time,.comment-byline small,.comment-deleted{color:var(--market-muted);font-size:12px}.comment-body{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;margin-top:8px}.reply-mention{color:var(--nc-accent)}.comment-actions{display:flex;gap:16px;margin-top:6px}.comment-actions button,.replies-toggle{background:none;border:0;padding:8px 0;color:var(--nc-accent);font-size:13px;min-height:40px}.comment-replies{margin-left:4px}.comment-replies .comment-avatar{width:28px;height:28px}.discussion textarea{width:100%;box-sizing:border-box}.comment-byline strong{overflow-wrap:anywhere;max-width:100%}@media(max-width:600px){.comment-entry{gap:8px}.comment-avatar{width:28px;height:28px}.comment-replies .comment-entry{gap:6px}.comment-replies .comment-avatar{display:none}}
</style>
